```javascript
function reduceListToSingleValue(list, func) {
  // Check if the provided function is a function
  if (!func || typeof func !== 'function') {
    throw new Error('The second argument must be a function');
  }

  // Use reduce to apply the function to all elements in the list
  return list.reduce((acc, item) => {
    return func(item, acc);
  }, null);
}

// Example usage
const numbers = [1, 2, 3, 4, 5];
const sum = (a, b) => a + b;

console.log(reduceListToSingleValue(numbers, sum)); // Output: 15
```

